from pathlib import Path
import shutil
import tempfile

backup = Path(tempfile.mkdtemp(prefix='php-ai-toolkit-doc-cleanup-'))
for rel in ('skills', 'packages/phpstan-ai-formatter/docs', 'packages/phpunit-ai-reporter/docs'):
    path = Path(rel)
    target = backup / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(path, target, symlinks=True)
    shutil.rmtree(path)
print('Removed root skills and formatter/reporter docs; preserved working copies in', backup)

for path in sorted(Path('packages').glob('*/guard.yaml')):
    text = path.read_text()
    prefix = 'rules/' if path.parent.name == 'guard-php' else 'vendor/k-kinzal/guard-php/rules/'
    marker = f'  - {prefix}docgen.yaml\n'
    imports = marker + f'  - {prefix}readme-md.yaml\n'
    if path.parent.name in ('phpstan-ai-formatter', 'phpunit-ai-reporter'):
        imports += f'  - {prefix}disable-doc.yaml\n'
    text = text.replace(marker, imports)
    text = text[:text.index('documentation:\n')] + "documentation:\n  scan:\n    - '*.md'\n"
    path.write_text(text)

